/* Profile design review. Account and inbox changes are browser-only, not identity/OAuth APIs. */
let profileData={name:'Alex Morgan',email:'alex@example.com',phone:'+1 202 555 0143',dateOfBirth:'1993-03-14',gender:'Not set'};
let profileInboxes=[{id:'gmail-alex',email:'alex@example.com',status:'synced',lastSync:'26 Oct · 9:00 AM'}];
let profileReviewOrigin='Profile',profileDialogTrigger=null;
const profileGlyphs={edit:'m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z',history:'M3 11a9 9 0 1 1 2 7M3 5v6h6M12 7v5l3 2',payments:'M3 7h18v13H3zM3 11h18M7 16h3',security:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6zM9 12l2 2 4-4',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4M12 17h.01',privacy:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3',terms:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7',logout:'M9 4H4v16h5M14 8l4 4-4 4M8 12h10',sparkle:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',mail:'M3 5h18v14H3zM3 6l9 7 9-7',refresh:'M20 7v5h-5M4 17v-5h5M6 8a7 7 0 0 1 12-2l2 6M4 12l2 6a7 7 0 0 0 12-2'};
const profileIcon=kind=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${profileGlyphs[kind]||profileGlyphs.help}"/>${kind==='help'?'<circle cx="12" cy="12" r="9"/>':''}</svg>`;
function profileContext(){const view=current.startsWith('Profile')?current:profileReviewOrigin;return {incomplete:view==='Profile · incomplete',hasPassword:view!=='Profile · social',provider:view==='Profile · social'?'Google':'Email'};}
function profileInitials(name){return name.trim().split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase()||'R';}
function profileInboxForView(){return profileInboxes[0];}
function profileImportedRecords(email,records=subscriptionListData()){return records.filter(r=>r.source==='Gmail'&&r.inboxEmail===email);}
function profilePaymentText(){const totals={};for(const p of paymentRecords.values())totals[p.currency]=(totals[p.currency]||0)+Math.round(p.amount*100);return Object.keys(totals).length?Object.entries(totals).map(([currency,cents])=>currency+' '+(cents/100).toFixed(2)).join(' · ')+' confirmed':'Confirmed payment history';}
function profileMenuRow(label,icon,{to='',action='',subtitle='',tone=''}={}){return `<button class="profile-menu-row ${tone}" ${to?`data-go="${to}"`:`data-profile-action="${action}"`}><span class="profile-menu-icon">${profileIcon(icon)}</span><span class="profile-menu-copy"><strong>${label}</strong>${subtitle?`<small>${escape(subtitle)}</small>`:''}</span><span class="profile-chevron" aria-hidden="true">›</span></button>`;}
function profileScreen(){
 profileReviewOrigin=current;const context=profileContext(),inbox=context.incomplete?null:profileInboxForView();
 return `<div class="profile-review"><div class="head"><h2>Profile</h2></div><div class="profile-account-header"><span class="profile-account-avatar" aria-hidden="true">${escape(profileInitials(profileData.name))}</span><div><h3>${escape(profileData.name)}</h3><p>${escape(profileData.email)}</p><small>Signed in with ${context.provider}</small></div><button class="profile-edit-icon" data-profile-action="edit" aria-label="Edit profile">${profileIcon('edit')}</button></div><section class="profile-inboxes"><div class="profile-section-heading"><h3>Connected inboxes</h3>${inbox?'<button data-profile-action="connect" aria-label="Connect another Gmail inbox">+ Connect</button>':''}</div>${inbox?`<button class="profile-inbox-row" data-profile-action="inbox"><span class="profile-inbox-logo">${platformLogo('Gmail')}</span><span class="profile-inbox-copy"><strong>${escape(inbox.email)}</strong><small class="${inbox.status==='synced'?'inbox-synced':'inbox-paused'}"><i aria-hidden="true"></i>${inbox.status==='synced'?'Synced':inbox.status==='reconnect'?'Reconnect needed':'Updates paused'}<span class="profile-sync-time"> · Last sync 26 Oct</span></small></span><span class="profile-chevron" aria-hidden="true">›</span></button>`:`<div class="profile-no-inbox"><span>${profileIcon('mail')}</span><div><strong>No inbox connected</strong><p>Find subscriptions and keep them up to date.</p></div><button data-profile-action="connect">Connect</button></div>`}</section><section class="profile-menu-section" aria-label="Your activity"><h3>Your activity</h3><div class="profile-menu-group">${profileMenuRow('History','history',{to:'History',subtitle:'Cancelled & expired subscriptions'})}${profileMenuRow('Payments','payments',{to:'Payments',subtitle:profilePaymentText()})}</div></section><section class="profile-menu-section" aria-label="Preferences and security"><h3>Preferences & security</h3><div class="profile-menu-group">${profileMenuRow('Reminder settings','refresh',{to:'Reminder settings'})}${context.hasPassword?profileMenuRow('Change password','security',{to:'Change password'}):profileMenuRow('Sign-in method','security',{action:'provider',subtitle:'Google account'})}</div></section><section class="profile-menu-section" aria-label="Help and legal"><h3>Help & legal</h3><div class="profile-menu-group">${profileMenuRow('Help & support','help',{action:'support'})}${profileMenuRow('Privacy Policy','privacy',{action:'privacy'})}${profileMenuRow('Terms of Service','terms',{action:'terms'})}</div></section><button class="profile-logout" data-profile-action="logout">${profileIcon('logout')}<span>Log out</span></button><p class="profile-app-version">Renewless · Version 0.0.1</p></div>`;
}
function profileEditScreen(){const ctx=profileContext();return `<div class="profile-edit-review">${heading('Edit profile',true)}<p class="profile-edit-intro">Keep your account details up to date.</p><form data-profile-edit novalidate>${profileEditField('Name','name',profileData.name,'text',true)}<div class="profile-readonly-email"><span>Login email</span><strong>${escape(profileData.email)}</strong><p>Email changes require verification.</p></div>${profileEditField('Phone · Optional','phone',ctx.incomplete?'':profileData.phone,'tel')}${profileEditField('Date of birth · Optional','dateOfBirth',ctx.incomplete?'':profileData.dateOfBirth,'date')}${selectField({label:'Gender · Optional',name:'gender',value:profileData.gender,options:['Not set','Female','Male','Other']})}<p class="profile-optional-note">Optional details are never required to use Renewless.</p><button class="primary" type="submit">Save changes</button></form></div>`;}
function profileEditField(label,name,value,type,required=false){return `<div class="profile-edit-field"><label for="profile-${name}">${label}</label><input id="profile-${name}" name="${name}" type="${type}" value="${escape(value)}" ${required?'required':''} ${type==='date'?'max="2026-10-30"':''} aria-describedby="profile-${name}-error"><p id="profile-${name}-error" class="field-error" hidden></p></div>`;}
let connectedInboxOrigin='Connected inbox',connectorPreview={running:false,error:''},connectorPreviewTimer;
function connectedInboxView(){
 const inbox=profileInboxForView();if(!inbox)return null;
 const running=connectorPreview.running||current==='Connected inbox · syncing';
 const reconnect=current==='Connected inbox · reconnect'||inbox.status==='reconnect';
 const error=current==='Connected inbox · error'?'Unable to sync right now. Your saved subscriptions haven’t changed.':connectorPreview.error;
 const status=reconnect?'reconnect':running?'syncing':error?'error':inbox.status;
 return {inbox,running,reconnect,error,status};
}
function connectedInboxHeader(title='Connected inbox'){return `<div class="head">${backButton({attributes:`data-profile-action="connector-back"`,label:"Back to Profile",className:""})}<h2>${title}</h2></div>`;}
function connectedInboxScreen(){
 const view=connectedInboxView();if(!view)return connectedInboxHeader()+'<p class="note">This inbox is no longer connected.</p>';
 const {inbox,running,reconnect,error,status}=view,imported=profileImportedRecords(inbox.email).length;
 const labels={paused:'Updates paused',synced:'Synced',syncing:'Syncing…',reconnect:'Reconnect needed',error:'Sync failed'};
 const main=reconnect?{label:'Reconnect Gmail',action:'reconnect',title:'Reconnect your inbox',copy:'Gmail needs your permission again. Your saved subscriptions are still available.'}:{label:running?'Syncing…':'Sync now',action:'sync',title:'Keep everything up to date',copy:'Check this inbox for new receipts and subscription updates.'};
 return `<div class="profile-inbox-detail">${connectedInboxHeader()}<div class="profile-inbox-identity">${platformLogo('Gmail')}<h3>${escape(inbox.email)}</h3><span class="inbox-connection-status inbox-state-${status}" ${running?'role="status"':''}>${running?'<i class="inbox-sync-spinner" aria-hidden="true"></i>':''}${labels[status]||'Updates paused'}</span></div><div class="profile-inbox-facts">${fr('Last successful sync',inbox.lastSync||'Not synced yet')}<button class="inbox-imported-link" data-profile-action="imports" aria-label="View ${imported} imported subscriptions"><span>Imported subscriptions</span><strong>${imported}<i aria-hidden="true">›</i></strong></button><div class="fieldrow inbox-access-row">${infoTooltip({id:'inbox-read-access',label:'Mailbox access',paragraphs:['Gmail authorizes read-only access to this inbox. Renewless cannot send, edit or delete your emails.','Relevant receipt details are filtered and may be processed by AI to identify subscriptions. This does not mean Google limits access to receipts only.','You can disconnect at any time. You’ll review affected imported subscriptions before confirming.']})}<span>Read-only</span></div></div>${error&&!reconnect?`<div class="inbox-sync-error" role="alert">${escape(error)}</div>`:''}${main?`<section class="profile-sync-info"><strong>${main.title}</strong><p>${main.copy}</p><button class="primary" data-profile-action="${main.action}" ${running?'disabled aria-disabled="true"':''}>${main.label}</button></section>`:''}<button class="profile-disconnect" data-profile-action="disconnect" ${running?'disabled':''}>Disconnect inbox</button><p class="note inbox-disconnect-note">You’ll review what gets removed before confirming.</p></div>`;
}
function inboxSubscriptionsScreen(){
 const inbox=profileInboxForView(),records=inbox?profileImportedRecords(inbox.email):[];
 return `<div class="inbox-imports-layout"><div class="head">${backButton({attributes:`data-profile-action="imports-back"`,label:"Back to connected inbox",className:""})}<h2>Imported subscriptions</h2></div><p class="inbox-imports-email">${escape(inbox?.email||'Inbox disconnected')}</p><p class="note">${records.length} subscription${records.length===1?'':'s'} imported from this inbox.</p>${records.length?`<div class="rows subscription-rows inbox-imported-rows">${records.map(r=>subscriptionCard(r,{attributes:`data-profile-record="${escape(r.id)}" aria-label="View ${escape(r.name)} imported subscription"`})).join('')}</div>`:`<div class="inbox-imports-empty">${mascotView({expression:'neutral',size:96})}<h3>No imported subscriptions</h3><p>Subscriptions imported from this inbox will appear here.</p></div>`}<p class="note">Manually added subscriptions aren’t included here.</p></div>`;
}
function previewInboxSync(){
 if(connectorPreview.running||current==='Connected inbox · syncing')return;
 connectorPreview={running:true,error:''};render();clearTimeout(connectorPreviewTimer);
 connectorPreviewTimer=setTimeout(()=>{connectorPreview={running:false,error:'Unable to sync right now. Your saved subscriptions haven’t changed.'};if(current.startsWith('Connected inbox'))render();},1200);
}
function closeProfileDialog(phone){phone.querySelector('.profile-dialog-overlay')?.remove();phone.querySelectorAll('[data-profile-dialog-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-profile-dialog-inert');});profileDialogTrigger?.focus();profileDialogTrigger=null;}
function openProfileDialog(trigger,type){const phone=trigger.closest('.phone'),disconnect=type==='disconnect',inbox=profileInboxes[0],count=inbox?profileImportedRecords(inbox.email).length:0,overlay=document.createElement('div');profileDialogTrigger=trigger;overlay.className='profile-dialog-overlay';overlay.innerHTML=`<div class="profile-dialog-shade" data-close-profile-dialog></div><section class="profile-dialog" role="dialog" aria-modal="true" aria-labelledby="profile-dialog-title"><header><h3 id="profile-dialog-title">${disconnect?'Disconnect this inbox?':'Log out of Renewless?'}</h3><button data-close-profile-dialog aria-label="Close confirmation">×</button></header><p>${disconnect?`Sync will stop for ${escape(inbox?.email||'this inbox')}. ${count} imported subscription${count===1?'':'s'} will be removed from your tracked list. Manually added subscriptions stay.`:'Your saved subscriptions stay on your account. You can sign in again anytime.'}</p><div><button class="secondary" data-close-profile-dialog>Cancel</button><button class="profile-confirm-danger" data-confirm-profile="${type}">${disconnect?'Disconnect':'Log out'}</button></div></section>`;phone.append(overlay);[...phone.children].filter(el=>el!==overlay&&!el.inert).forEach(el=>{el.inert=true;el.dataset.profileDialogInert='true';});overlay.querySelector('button').focus();}
function resetProfilePreview(){clearTimeout(connectorPreviewTimer);connectorPreview={running:false,error:''};connectedInboxOrigin='Connected inbox';profileData={name:'Alex Morgan',email:'alex@example.com',phone:'+1 202 555 0143',dateOfBirth:'1993-03-14',gender:'Not set'};profileInboxes=[{id:'gmail-alex',email:'alex@example.com',status:'synced',lastSync:'26 Oct · 9:00 AM'}];profileReviewOrigin='Profile';profileDialogTrigger=null;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-profile-action]'),close=event.target.closest('[data-close-profile-dialog]'),confirm=event.target.closest('[data-confirm-profile]');if(button){const name=button.dataset.profileAction;if(name==='edit')go('Edit profile');else if(name==='inbox')go('Connected inbox');else if(name==='connector-back')go(profileReviewOrigin);else if(name==='imports'){connectedInboxOrigin=current;go('Inbox subscriptions');}else if(name==='imports-back')go(connectedInboxOrigin);else if(name==='sync')previewInboxSync();else if(name==='reconnect')toast('Gmail reconnection is unavailable right now. Your saved subscriptions are unchanged.');else if(name==='connect')go('Gmail · scanning');else if(name==='logout'||name==='disconnect')openProfileDialog(button,name);else if(name==='provider')toast('You sign in with Google. Manage your password through your Google account.');else toast(name==='support'?'Support is currently unavailable. Please try again later.':'This page is currently unavailable. Please try again later.');}else if(close)closeProfileDialog(close.closest('.phone'));else if(confirm){if(confirm.dataset.confirmProfile==='disconnect'){const inbox=profileInboxes[0];if(inbox){profileImportedRecords(inbox.email).forEach(r=>{trialRecords.set(r.id,{...r,status:'Deleted'});reminderPreferences.delete(r.id);});profileInboxes=profileInboxes.filter(r=>r.id!==inbox.id);}go(profileReviewOrigin);toast('Inbox disconnected. Manual subscriptions were kept.');}else{ob.account=false;go('Welcome');toast('You’re logged out.');}profileDialogTrigger=null;}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-profile-edit]');if(!form)return;event.preventDefault();form.querySelectorAll('.field-error').forEach(el=>el.hidden=true);form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));const name=form.elements.name.value.trim(),dob=form.elements.dateOfBirth.value;let field=null,message='';if(!name){field=form.elements.name;message='Enter your name.';}else if(dob&&dob>'2026-10-30'){field=form.elements.dateOfBirth;message='Choose a date in the past.';}if(field){const error=form.querySelector('#'+field.id+'-error');error.textContent=message;error.hidden=false;field.setAttribute('aria-invalid','true');field.focus();return;}profileData={...profileData,name,phone:form.elements.phone.value.trim(),dateOfBirth:dob,gender:form.elements.gender.value};go(profileReviewOrigin);toast('Profile updated.');});
document.addEventListener('keydown',event=>{const overlay=document.querySelector('.profile-dialog-overlay');if(!overlay)return;if(event.key==='Escape'){event.preventDefault();closeProfileDialog(overlay.closest('.phone'));}else if(event.key==='Tab'){const controls=[...overlay.querySelectorAll('button')],first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

document.addEventListener('click',event=>{const row=event.target.closest('[data-profile-record]');if(!row)return;const r=subscriptionListData().find(item=>item.id===row.dataset.profileRecord);if(!r){toast('This subscription is no longer available.');return;}state.manual={...r};demoName=r.name;demoPrice=r.price;go('Detail');});

/* Password-change preview. Never persists credentials or claims a live password update. */
function changePasswordErrors(values){
 const errors={};
 if(!values.currentPassword)errors.currentPassword='Enter your current password.';
 if(!values.newPassword)errors.newPassword='Enter a new password.';
 else if(values.newPassword.length<6)errors.newPassword='Use at least 6 characters.';
 else if(values.newPassword===values.currentPassword)errors.newPassword='Choose a password different from your current one.';
 if(!values.confirmPassword)errors.confirmPassword='Confirm your new password.';
 else if(values.confirmPassword!==values.newPassword)errors.confirmPassword='Passwords don’t match.';
 return errors;
}
function changePasswordField(label,name,autocomplete){return `<div class="cp-field"><label for="cp-${name}">${label}</label><div class="cp-input-wrap"><input id="cp-${name}" name="${name}" type="password" autocomplete="${autocomplete}" autocapitalize="none" spellcheck="false" required ${name==='currentPassword'?'':'minlength="6"'} aria-describedby="cp-${name}-error${name==='newPassword'?' cp-password-hint':''}"><button type="button" class="cp-visibility" data-cp-visibility="${name}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/><path class="cp-eye-slash" d="m4 3 16 18"/></svg></button></div>${name==='newPassword'?'<p class="cp-hint" id="cp-password-hint">Use at least 6 characters.</p>':''}<p class="field-error" id="cp-${name}-error" aria-live="polite" hidden></p></div>`;}
function changePasswordScreen(){
 const header=`<div class="head cp-head">${backButton({attributes:`data-cp-back`,label:"Back to Profile",className:""})}<h2>Change password</h2></div>`;
 if(!profileContext().hasPassword)return `<div class="change-password-review">${header}<section class="cp-provider"><span class="cp-security-icon">${profileIcon('security')}</span><h3>You sign in with Google</h3><p>Your Google account manages your password. You don’t need a separate Renewless password.</p><button class="secondary" data-cp-back>Back to Profile</button></section></div>`;
 return `<div class="change-password-review">${header}<div class="cp-intro"><span class="cp-security-icon">${profileIcon('security')}</span><h3>A fresh password.<br>A little more peace of mind.</h3><p>Update the password you use to sign in to Renewless.</p></div><form id="change-password-form" data-change-password novalidate>${changePasswordField('Current password','currentPassword','current-password')}${changePasswordField('New password','newPassword','new-password')}${changePasswordField('Confirm new password','confirmPassword','new-password')}<div class="cp-request-error" role="alert" hidden></div></form><div class="password-change-footer"><button class="primary" form="change-password-form" type="submit">Update password</button><p>Your tracked subscriptions stay unchanged.</p></div></div>`;
}
function changePasswordValues(form){return {currentPassword:form.elements.currentPassword.value,newPassword:form.elements.newPassword.value,confirmPassword:form.elements.confirmPassword.value};}
function showChangePasswordErrors(form,errors,focusFirst=false){for(const name of ['currentPassword','newPassword','confirmPassword']){const field=form.elements[name],error=form.querySelector('#cp-'+name+'-error'),message=errors[name]||'';error.textContent=message;error.hidden=!message;field.setAttribute('aria-invalid',String(!!message));}if(focusFirst){const first=Object.keys(errors)[0];if(first)form.elements[first].focus();}}
document.addEventListener('click',event=>{const eye=event.target.closest('[data-cp-visibility]'),back=event.target.closest('[data-cp-back]');if(back){go(profileReviewOrigin);return;}if(!eye)return;const form=eye.closest('form'),field=form.elements[eye.dataset.cpVisibility],show=field.type==='password';field.type=show?'text':'password';eye.setAttribute('aria-pressed',String(show));eye.setAttribute('aria-label',(show?'Hide ':'Show ')+field.closest('.cp-field').querySelector('label').textContent.toLowerCase());field.focus();});
document.addEventListener('input',event=>{const form=event.target.closest('[data-change-password]');if(!form)return;form.querySelector('.cp-request-error').hidden=true;if(form.dataset.submitted)showChangePasswordErrors(form,changePasswordErrors(changePasswordValues(form)));});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-change-password]');if(!form)return;event.preventDefault();if(form.dataset.busy==='true')return;form.dataset.submitted='true';const errors=changePasswordErrors(changePasswordValues(form));showChangePasswordErrors(form,errors,true);const requestError=form.querySelector('.cp-request-error');requestError.hidden=true;if(Object.keys(errors).length)return;form.dataset.busy='true';form.setAttribute('aria-busy','true');const button=form.closest('.phone').querySelector('.password-change-footer button');button.disabled=true;button.textContent='Updating…';form.querySelectorAll('input,.cp-visibility').forEach(el=>el.disabled=true);setTimeout(()=>{if(!form.isConnected)return;form.dataset.busy='false';form.removeAttribute('aria-busy');form.querySelectorAll('input,.cp-visibility').forEach(el=>el.disabled=false);button.disabled=false;button.textContent='Update password';requestError.textContent='Unable to update your password right now. Please try again.';requestError.hidden=false;},1000);});
